import{_ as o,I as e,g as l,j as r}from"./chunks/framework.CjoWWfVe.js";const u=JSON.parse('{"title":"Глобальные настройки","description":"Смена языка, валюты учета и инструменты аварийного сброса данных в ОмниКрафт ЕРП.","frontmatter":{"title":"Глобальные настройки","description":"Смена языка, валюты учета и инструменты аварийного сброса данных в ОмниКрафт ЕРП.","order":16},"headers":[],"relativePath":"ru/docs/global-settings.md","filePath":"ru/docs/global-settings.md"}'),a={name:"ru/docs/global-settings.md"};function n(i,t,s,d,c,g){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="⚙️-глобальные-настроики-язык-валюта-и-безопасность" tabindex="-1">⚙️ Глобальные настройки: Язык, Валюта и Безопасность <a class="header-anchor" href="#⚙️-глобальные-настроики-язык-валюта-и-безопасность" aria-label="Permalink to &quot;⚙️ Глобальные настройки: Язык, Валюта и Безопасность&quot;">​</a></h1><p>В отличие от <em>Настроек пространства</em>, которые влияют на экономику конкретного бизнеса (ставки, наценки, накладные расходы), <strong>Глобальные настройки</strong> задают фундаментальные правила работы всего приложения и вашей локальной базы данных.</p><p>Чтобы открыть их, нажмите в верхнем меню <strong>Файл ➔ Настройки программы</strong>.</p><hr><h2 id="🌍-локализация-и-валюта" tabindex="-1">🌍 Локализация и Валюта <a class="header-anchor" href="#🌍-локализация-и-валюта" aria-label="Permalink to &quot;🌍 Локализация и Валюта&quot;">​</a></h2><h3 id="_1-язык-интерфеиса" tabindex="-1">1. Язык интерфейса <a class="header-anchor" href="#_1-язык-интерфеиса" aria-label="Permalink to &quot;1. Язык интерфейса&quot;">​</a></h3><p>Программа поддерживает полную локализацию интерфейса. При самом первом запуске ОмниКрафт ЕРП автоматически сканирует язык вашей операционной системы и подстраивается под него. Вы можете в любой момент переключиться между <strong>Русским (RU)</strong> и <strong>English (EN)</strong>.</p><ul><li><strong>Как работает:</strong> Изменение языка требует полного перезапуска приложения, чтобы все системные окна, категории ДДС и справочники корректно перевелись и подгрузились из словарей.</li></ul><h3 id="_2-валюта-учета" tabindex="-1">2. Валюта учета <a class="header-anchor" href="#_2-валюта-учета" aria-label="Permalink to &quot;2. Валюта учета&quot;">​</a></h3><p>По умолчанию программа подтягивает символ национальной валюты из региональных настроек вашей ОС (например, <code>₽</code>, <code>$</code>, <code>€</code>, <code>₸</code>, <code>₺</code>). Вы можете изменить её на любую другую через удобный встроенный поиск (просто начните вводить название, например, <em>«лира»</em> или <em>«юань»</em>).</p><div class="warning custom-block"><p class="custom-block-title">Защита исторических данных</p><p>Кнопка смены валюты <strong>автоматически блокируется</strong>, как только вы начинаете вести реальный учет (создаете первую закупку, продажу или запись в ДДС). Это сделано для защиты вашей финансовой отчетности. Если бы программа позволяла на лету менять валюту с рублей на доллары, все ваши прошлые чеки, балансы и графики аналитики мгновенно превратились бы в математическую кашу. <strong>Что делать, если вы переехали в другую страну?</strong> Вам потребуется выполнить «Сброс учета» (см. ниже), чтобы начать вести книги в новой валюте с чистого листа, сохранив при этом справочники и рецепты.</p></div><hr><h2 id="🤖-интеллектуальные-функции-ии" tabindex="-1">🤖 Интеллектуальные функции (ИИ) <a class="header-anchor" href="#🤖-интеллектуальные-функции-ии" aria-label="Permalink to &quot;🤖 Интеллектуальные функции (ИИ)&quot;">​</a></h2><p>ОмниКрафт ЕРП предоставляет интеллектуальные функции помощи мастеру на базе искусственного интеллекта по принципу использования собственного ключа API (прямой доступ к нейросетям без серверов-посредников).</p><p>Все запросы к нейросетям отправляются <strong>напрямую с вашего компьютера</strong> на серверы выбранного поставщика. Ваши коммерческие данные, рецепты, клиентские базы и финансовые отчеты никогда не передаются на промежуточные серверы разработчиков ОмниКрафт ЕРП, что обеспечивает 100% приватность и конфиденциальность.</p><h3 id="_1-поддерживаемые-поставщики-неиросетеи" tabindex="-1">1. Поддерживаемые поставщики нейросетей <a class="header-anchor" href="#_1-поддерживаемые-поставщики-неиросетеи" aria-label="Permalink to &quot;1. Поддерживаемые поставщики нейросетей&quot;">​</a></h3><ul><li><strong>OpenAI</strong> (<code>gpt-4o</code>, <code>gpt-4o-mini</code>, <code>o1</code>, <code>o3-mini</code>);</li><li><strong>DeepSeek</strong> (<code>deepseek-chat</code>, <code>deepseek-reasoner</code>);</li><li><strong>Google Gemini</strong> (<code>gemini-1.5-flash</code>, <code>gemini-1.5-pro</code>, <code>gemini-2.0</code>);</li><li><strong>Anthropic</strong> (<code>claude-3-5-sonnet</code>, <code>claude-3-5-haiku</code>, <code>claude-3-opus</code>);</li><li><strong>OpenRouter</strong> (доступ к каталогу моделей через единый ключ API);</li><li><strong>Собственный сервер / локальная служба</strong> (<code>Ollama</code>, <code>vLLM</code> и локальные модели).</li></ul><p>Настройки ИИ вынесены в отдельную вкладку «ИИ-Агент» в окне настроек программы с поддержкой перехода в один клик из подсказок ассистента и рабочих форм:</p><ul><li><strong>Изолированное сохранение параметров по поставщикам:</strong> Каждый поставщик нейросетей сохраняет свои собственные учётные данные (ключ API, выбранную модель и адрес сервера). При переключении поставщика в окне настроек автоматически подгружаются его сохранённые параметры, исключая случайную перезапись ключей.</li><li><strong>Реактивный базовый URL и локальные модели:</strong> Для работы с локальными нейросетями (<code>Ollama</code>, <code>LM Studio</code>, кастомные шлюзы) предусмотрено поле «Базовый URL» со всплывающей справкой <code>(?)</code>. При вводе локального адреса выпадающие списки автоматически блокируются, а ниже открывается удобное поле прямого указания системного имени модели (<code>Model ID</code>).</li><li><strong>Точный выбор модели без ложных совпадений:</strong> Модальное окно выбора моделей выполняет поиск исключительно по подтверждённому списку нейросетей поставщика без генерации фиктивных записей из поисковых запросов.</li><li><strong>Аккуратное отображение ключа API:</strong> Поле ввода ключа выдержано в едином системном масштабе, обеспечивая комфортный размер символов маскирования пароля и безопасный просмотр при нажатии на значок глаза.</li><li><strong>Автоматическая диагностика связи:</strong> Система непрерывно верифицирует статус подключения с живой индикацией проверки и лаконичным подтверждением готовности к работе.</li><li><strong>Самовосстановление хранилища (<code>Self-Healing Vault</code>):</strong> При переносе базы данных на другой компьютер срабатывает механизм безопасной защиты ключа, деликатно запрашивая повторный ввод без сбоев программы.</li></ul><h3 id="_2-аппаратная-защита-ключеи-windows-dpapi" tabindex="-1">2. Аппаратная защита ключей (<code>Windows DPAPI</code>) <a class="header-anchor" href="#_2-аппаратная-защита-ключеи-windows-dpapi" aria-label="Permalink to &quot;2. Аппаратная защита ключей (`Windows DPAPI`)&quot;">​</a></h3><p>Ваш ключ API сохраняется в зашифрованном виде с использованием технологии аппаратной криптографической защиты операционной системы (<code>Windows DPAPI</code>). Ключ привязан к учетной записи и аппаратному обеспечению вашего компьютера, что исключает его компрометацию сторонними программами или при случайном копировании файлов настроек.</p><h3 id="_3-кнопки-помощники-«кнопки-искры»-✨-в-формах" tabindex="-1">3. Кнопки-помощники («кнопки-искры» ✨) в формах <a class="header-anchor" href="#_3-кнопки-помощники-«кнопки-искры»-✨-в-формах" aria-label="Permalink to &quot;3. Кнопки-помощники («кнопки-искры» ✨) в формах&quot;">​</a></h3><p>При включенном ИИ в ключевых рабочих пространствах программы становятся доступны кнопки экспресс-анализа:</p><ul><li><strong>Калькулятор тиража:</strong> экономический аудит себестоимости партии, выявление главного драйвера издержек и советы по оптимизации цены.</li><li><strong>Склад сырья:</strong> генерация профессионального описания номенклатуры, характеристик материала и правил складского хранения в один клик.</li><li><strong>Верстак производства:</strong> формирование технологической памятки мастера с контрольными точками качества и оценкой сырьевых рисков.</li></ul><p>Если ключ API еще не настроен, нажатие на кнопку-помощник отобразит деликатную подсказку с возможностью перейти к настройкам в один клик. Программа всегда остается на 100% работоспособной даже без подключения ИИ.</p><h3 id="_4-внутреннии-ии-помощник-выдвижная-правая-панель" tabindex="-1">4. Внутренний ИИ-помощник (Выдвижная правая панель) <a class="header-anchor" href="#_4-внутреннии-ии-помощник-выдвижная-правая-панель" aria-label="Permalink to &quot;4. Внутренний ИИ-помощник (Выдвижная правая панель)&quot;">​</a></h3><p>С правой стороны главного окна программы расположена компактная выдвижная панель персонального ИИ-помощника.</p><ul><li><strong>Ненавязчивость по умолчанию:</strong> Панель свернута в тонкую полосу (38 пикселей) с аккуратным значком и не отвлекает мастера от повседневной работы.</li><li><strong>Контекст экрана («карта + детали по запросу»):</strong> Помощник видит активную вкладку программы (Склад, Верстак, Калькулятор, Продажи) и отвечает на вопросы с учетом текущих остатков и параметров. Вы можете в любой момент отключить передачу контекста экрана с помощью переключателя в шапке панели или нажать значок глаза, чтобы увидеть точный снимок отправляемых данных.</li><li><strong>Селектор зоны охвата (Изоляция вкладки или Вся система):</strong> В шапке панели расположен интерактивный переключатель режима работы: «🔒 Вкладка» (строгая изоляция действий рамками открытого экрана) и «🌐 Вся система» (сквозная интеллектуальная маршрутизация с доступом ко всем инструментам программы).</li><li><strong>Безопасность операций (Человек в контуре управления):</strong> Если ИИ предлагает выполнить операцию (например, создать персональную ссылку или обновить статус), он выводит карточку действия. Любые изменения данных выполняются <strong>только после вашего прямого подтверждения</strong> кнопкой «Выполнить».</li><li><strong>Приватный режим:</strong> При выборе локальной модели (например, Ollama) отображается зеленый знак «Офлайн», гарантирующий, что ваши запросы обрабатываются исключительно на вашем компьютере.</li></ul><h3 id="_5-глобальная-инструкция-для-ии" tabindex="-1">5. Глобальная инструкция для ИИ <a class="header-anchor" href="#_5-глобальная-инструкция-для-ии" aria-label="Permalink to &quot;5. Глобальная инструкция для ИИ&quot;">​</a></h3><p>Системный контекст внутреннего помощника формируется по модульному принципу:</p><ul><li><strong>Неизменяемые гарантии ядра:</strong> Вшитые правила роли цехового наставника, финансовые инварианты (учет себестоимости сырья по скользящей средней МАК, списание готовой продукции партиями по ФИФО, целочисленное хранение денежных величин) и принцип нулевого разрушения (Zero-Destruction) строго защищены и соблюдаются ядром программы.</li><li><strong>Специфика вашей мастерской (системный контекст):</strong> Настраиваемый профиль в Настройках программы с готовым универсальным цеховым манифестом для ремесленников (расчёт полной себестоимости, учёт сырья и расходников, оценка нормо-часов, допуск на технологический брак и амортизация оборудования). Мастер может в любой момент скорректировать формулировку под своё ремесло.</li><li><strong>Правила рабочего пространства:</strong> Контекстные инструкции, зависящие от открытого пространства (производство, услуги, личный капитал).</li><li><strong>Инструкции открытого раздела:</strong> Специфические инструкции под активный экран (Склад, Верстак, Калькулятор, Продажи, ДДС).</li><li><strong>Целевые задачи:</strong> Микро-шаблоны кнопок экспресс-анализа в интерфейсе.</li></ul><p>Благодаря архитектуре с неизменяемым началом системного запроса постоянные инструкции сохраняются в оперативной памяти языковой модели, что снижает время отклика и сокращает расход сетевых ресурсов.</p><h3 id="_6-долговременная-память-самообучение-и-лимиты-токенов" tabindex="-1">6. Долговременная память, самообучение и лимиты токенов <a class="header-anchor" href="#_6-долговременная-память-самообучение-и-лимиты-токенов" aria-label="Permalink to &quot;6. Долговременная память, самообучение и лимиты токенов&quot;">​</a></h3><p>ОмниКрафт ЕРП оснащен встроенной системой долговременной памяти на базе легковесного локального поискового движка <code>SQLite FTS5</code> (ранжирование BM25). Ассистент запоминает привычки, технологические нюансы и номенклатурные правила мастера без использования тяжелых внешних библиотек.</p><ul><li><strong>Управление режимами обучения:</strong> В окне настроек доступен тумблер включения/выключения автоматического обучения ассистента. Вы можете выбрать удобный режим: с показом уведомлений для подтверждения выученных правил мастером или в режиме полного автопилота без лишних вопросов.</li><li><strong>Контроль лимита токенов и уплотнение памяти:</strong> Для предотвращения разрастания системных запросов предусмотрен настраиваемый лимит токенов (по умолчанию 1000 токенов). При заполнении памяти механизм уплотнения деактивирует устаревшие и наименее уверенные правила, сохраняя высокую скорость и точность ответов без лишних затрат.</li><li><strong>Обучение на отказах (Reflexion Loop):</strong> При отклонении предложенного ассистентом действия (кнопка «Отклонить» на карточке действия) открывается компактный диалог. Если вы укажете причину отказа (например, <em>«Мы не фасуем масло в бутылки по 1 л, только по 0.5 л»</em>), ассистент сформулирует правило и сохранит его для активного раздела, чтобы в будущем предлагать только корректные операции.</li><li><strong>Закрепление правил (кнопка-булавка 📌):</strong> В правом верхнем углу любого сообщения ассистента доступна кнопка закрепления. Вы можете в один клик зафиксировать удачную подсказку или технологический стандарт в базу памяти.</li><li><strong>Инспектор базы знаний в Настройках:</strong> В разделе «ИИ-Агент» модального окна настроек программы расположен полный список выученных правил. Вы можете временно отключать правила переключателем, удалять ненужные записи или добавлять новые правила вручную с указанием области действия (вся программа или конкретный раздел).</li><li><strong>Изоляция личных финансов:</strong> Правила пространства «Мой капитал» хранятся изолированно и никогда не подмешиваются в запросы коммерческих пространств мастерской.</li></ul><h3 id="_7-внешние-ии-агенты-служба-mcp" tabindex="-1">7. Внешние ИИ-агенты (служба <code>MCP</code>) <a class="header-anchor" href="#_7-внешние-ии-агенты-служба-mcp" aria-label="Permalink to &quot;7. Внешние ИИ-агенты (служба `MCP`)&quot;">​</a></h3><p>ОмниКрафт ЕРП поддерживает стандартизированный протокол взаимодействия с внешними автономными агентами (протокол контекста модели — <code>Model Context Protocol</code>, <code>MCP</code>, спецификация 2024-11-05). Это позволяет подключать внешние среды разработки и агентские клиенты (<code>Cursor</code>, <code>Claude Desktop</code>, <code>Antigravity</code>) напрямую к программе через локальный межпроцессный канал (<code>stdio</code>).</p><ul><li><strong>Единая точка входа:</strong> Все зарегистрированные модули программы автоматически предоставляют свои инструменты через единый реестр. Внешний агент подключается одним конфигурационным файлом и видит доступные возможности всей системы.</li><li><strong>Токен сопряжения и отзыв в один клик:</strong> Для безопасной авторизации внешнего агента в Настройках программы генерируется уникальный криптографический токен сопряжения. Если вы хотите закрыть доступ агенту, достаточно нажать кнопку «Отозвать токен» — сопряжение мгновенно аннулируется.</li><li><strong>Готовая конфигурация:</strong> По нажатию кнопки «Скопировать <code>JSON</code>-конфиг» программа формирует готовый блок настроек для вставки в конфигурационный файл вашего агента (<code>claude_desktop_config.json</code> или <code>cursor/mcp.json</code>).</li><li><strong>Доверенный режим (Защита от несанкционированных изменений):</strong> По умолчанию внешнему агенту разрешены только безопасные операции чтения (<code>read-only</code>). Любые изменяющие операции (<code>mutating</code>), такие как создание ссылок или изменение статусов, блокируются на уровне ядра. Для их разрешения необходимо осознанно активировать переключатель «Доверенный режим» в Настройках программы.</li><li><strong>Сквозной журнал аудита:</strong> Каждое действие внешнего агента фиксируется в системном журнале с фиксацией имени агента, параметров вызова, статуса и времени отклика в миллисекундах.</li></ul><h3 id="_8-иерархические-навыки-и-системные-реестры-справка-➔-системные-реестры" tabindex="-1">8. Иерархические навыки и системные реестры (Справка ➔ Системные реестры) <a class="header-anchor" href="#_8-иерархические-навыки-и-системные-реестры-справка-➔-системные-реестры" aria-label="Permalink to &quot;8. Иерархические навыки и системные реестры (Справка ➔ Системные реестры)&quot;">​</a></h3><p>Программа предоставляет единый центр управления сценариями автоматизации и инспекции системных инструкций — <strong>«Реестр навыков и промптов ИИ»</strong>, доступный через верхнее меню <strong>Справка ➔ Системные реестры</strong>.</p><ul><li><strong>Древовидная структура разделов:</strong> Экран реестра организован в виде трехуровневого дерева (<code>Программа ➔ Пространства ➔ Вкладки разделов</code>). Выбрав любой узел (например, Склад, Мастерская или Калькулятор), мастер может ознакомиться с действующей системной инструкцией этого уровня и списком закрепленных за ним сценариев.</li><li><strong>Библиотека навыков (Повторно используемые сценарии):</strong> Каждый навык представляет собой готовый шаблон рабочего запроса с привязкой к области действия (<code>глобальный</code>, <code>пространство</code> или <code>вкладка</code>). Вы можете временно отключать встроенные навыки переключателем, а также создавать собственные сценарии через кнопку «+ Новый навык».</li><li><strong>Интерактивные чипсы подсказок (Suggested Chips):</strong> Вкладочные навыки автоматически выводятся в виде интерактивных кнопок-чипсов в верхней части развернутой панели ассистента. При переключении экранов состав чипсов мгновенно адаптируется под открытый раздел, позволяя запустить проверку дефицита сырья или аудит себестоимости в один клик.</li><li><strong>Экспорт карты ИИ в Markdown:</strong> В шапке окна реестра расположена кнопка «Экспорт карты ИИ в Markdown», формирующая полный структурированный отчет по всем уровням системных инструкций (L0–L3), библиотеке навыков, зарегистрированным инструментам и выученным правилам с автоматическим копированием в буфер обмена.</li></ul><h3 id="_9-режим-агента-пк-и-четырехуровневая-защита" tabindex="-1">9. Режим агента ПК и четырёхуровневая защита <a class="header-anchor" href="#_9-режим-агента-пк-и-четырехуровневая-защита" aria-label="Permalink to &quot;9. Режим агента ПК и четырёхуровневая защита&quot;">​</a></h3><p>Для безопасной работы ИИ-помощника с файловой системой и внешними утилитами операционной системы в ОмниКрафт ЕРП встроен четырёхуровневый защитный шлюз:</p><ul><li><strong>Тумблер «Режим агента ПК»:</strong> По умолчанию режим строго выключен. Пока тумблер выключен в настройках ассистента, программа блокирует любые попытки обращения к файлам вне приложения и вызовам команд ОС.</li><li><strong>Белый список директорий:</strong> Вы можете указать доверенные папки (например, <code>C:\\Отчеты; C:\\Документы</code>), ограничив область сохранения и чтения файлов только этими путями. Прямой доступ к системным файлам баз данных (<code>*.db</code>, <code>*.sqlite</code>) и ключам конфигурации (<code>.env</code>) категорически запрещен.</li><li><strong>Четырёхуровневая матрица авторизации:</strong><ul><li>🟢 <strong>Класс 1 (Запросы ERP):</strong> Чтение остатков, расчет себестоимости и аналитика — выполняются автоматически без лишних подтверждений.</li><li>🟡 <strong>Класс 2 (Мутации ERP):</strong> Списание материалов, проведение продаж и накладных — выводят карточку действия с кнопками «Выполнить» и «Отклонить».</li><li>🟠 <strong>Класс 3 (Файлы и оборудование):</strong> Сохранение отчетов, чтение накладных, печать этикеток — требуют явного модального подтверждения пути к файлу или целевого принтера.</li><li>🔴 <strong>Класс 4 (Системные команды ОС):</strong> Запуск внешних бинарников и команд терминала — отображают блокирующее красное окно безопасности с показом полного текста команды, валидацией политики нулевого разрушения (Zero-Destruction) и аппаратной трехсекундной задержкой кнопки подтверждения для защиты мастера от случайного клика.</li></ul></li></ul><hr><h2 id="☢️-опасная-зона-danger-zone" tabindex="-1">☢️ Опасная зона (Danger Zone) <a class="header-anchor" href="#☢️-опасная-зона-danger-zone" aria-label="Permalink to &quot;☢️ Опасная зона (Danger Zone)&quot;">​</a></h2><p>В нижней части окна настроек расположены инструменты для радикального вмешательства в базу данных. Эти кнопки следует использовать только осознанно.</p><h3 id="🧹-сброс-учета-очистка-истории" tabindex="-1">🧹 Сброс учета (Очистка истории) <a class="header-anchor" href="#🧹-сброс-учета-очистка-истории" aria-label="Permalink to &quot;🧹 Сброс учета (Очистка истории)&quot;">​</a></h3><p>Этот инструмент предназначен для <strong>«обнуления» операционной памяти</strong> бизнеса без потери его инфраструктуры. Он идеально подходит, если вы использовали программу в тестовом режиме, набили много черновых чеков, и теперь хотите начать вести реальные дела с чистого листа.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Что будет УДАЛЕНО (Журналы)</th><th style="text-align:left;">Что будет ОБНУЛЕНО (Остатки)</th><th style="text-align:left;">Что будет СОХРАНЕНО (Инфраструктура)</th></tr></thead><tbody><tr><td style="text-align:left;">• Вся история продаж (чеки)</td><td style="text-align:left;">• Физические остатки сырья на складе</td><td style="text-align:left;">• Всё оборудование и активы (Мастерская)</td></tr><tr><td style="text-align:left;">• Журнал складских движений</td><td style="text-align:left;">• Остатки готовой продукции (Витрина)</td><td style="text-align:left;">• Справочники сырья и ссылки на поставщиков</td></tr><tr><td style="text-align:left;">• Реестр денежных операций (ДДС)</td><td style="text-align:left;">• Сальдо кассы и история ДДС</td><td style="text-align:left;">• Все шаблоны изделий и Рецепты</td></tr><tr><td style="text-align:left;">• Очередь производства (Верстак)</td><td style="text-align:left;">• Себестоимость партий ФИФО</td><td style="text-align:left;">• Категории, упаковки, глобальные настройки</td></tr></tbody></table><p>Перед выполнением очистки программа автоматически сделает теневой бэкап базы данных. После нажатия кнопки <strong>«Очистить историю»</strong> ОмниКрафт ЕРП предложит автоматическую перезагрузку. Вы получите чистую мастерскую, готовую к инвентаризации стартовых остатков (см. <a href="./getting-started">Быстрый старт</a>).</p><h3 id="💥-полныи-сброс-factory-reset" tabindex="-1">💥 Полный сброс (Factory Reset) <a class="header-anchor" href="#💥-полныи-сброс-factory-reset" aria-label="Permalink to &quot;💥 Полный сброс (Factory Reset)&quot;">​</a></h3><p>Это кнопка «Красная таблетка». Она <strong>безвозвратно удаляет абсолютно всё</strong> из локальной базы данных SQLite.</p><ul><li>Все таблицы, справочники, рецепты, чеки, остатки, настройки и лицензионные ключи превращаются в пустоту.</li><li>При следующем запуске программа создаст базу заново, как будто вы только что скачали и установили ОмниКрафт ЕРП в самый первый раз.</li></ul><div class="danger custom-block"><p class="custom-block-title">Внимание!</p><p>Перед использованием этой функции <strong>обязательно</strong> сделайте ручной экспорт данных (<code>Файл ➔ Экспорт данных ➔ Резервная копия базы .db</code>), если есть хоть малейший шанс, что эта информация вам когда-либо понадобится. Восстановить данные после полного сброса без файла бэкапа невозможно.</p></div><hr><h2 id="🔄-автоматическая-перезагрузка" tabindex="-1">🔄 Автоматическая перезагрузка <a class="header-anchor" href="#🔄-автоматическая-перезагрузка" aria-label="Permalink to &quot;🔄 Автоматическая перезагрузка&quot;">​</a></h2><p>Любое изменение в Глобальных настройках (смена языка, валюты или сброс учета) требует пересборки конфигурации в оперативной памяти. После сохранения изменений программа предложит вам <strong>перезагрузиться сейчас</strong> или сделать это позже.</p><p>Во время перезагрузки ОмниКрафт ЕРП заботливо сохраняет геометрию вашего окна (размер и положение на экране), чтобы вы продолжили работу ровно там, где остановились.</p>',59)])])}const p=o(a,[["render",n]]);export{u as __pageData,p as default};
